describe('Notification Click Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should navigate to relevant content when clicking a notification', () => {
    // Intercept the API call for notification data
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify notifications are displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'New message from John');

    // Click the notification to navigate
    cy.get('[data-testid="notification-item"]').click();

    // Verify navigation to the correct page
    cy.url().should('include', '/messages');
    cy.get('[data-testid="message-header"]').should('be.visible');
    cy.get('[data-testid="message-header"]').should('contain', 'John Doe');
  });

  it('should handle clicking a notification with no associated content', () => {
    // Intercept the API call for notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify notification with no content exists
    cy.get('[data-testid="notification-item-empty"]').should('be.visible');
    cy.get('[data-testid="notification-item-empty"]').should('contain', 'System update');

    // Click the empty notification
    cy.get('[data-testid="notification-item-empty"]').click();

    // Verify navigation to a generic or home page
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-welcome"]').should('be.visible');
    cy.get('[data-testid="dashboard-welcome"]').should('contain', 'Welcome back');
  });
});
